def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([1, 1, 2, 4]), fmt([4, 4, 4]), fmt([5, 1, 1, 1, 10]), fmt([1, 1]), fmt([3, 1])]
    for n in (2, 3, 4, 5, 6, 7):
        for _ in range(3):
            hi = rng.choice([3, 8, 30])
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 3) for _ in range(n)]))
    tests.append(fmt([1] * n))
    # doubling prefix chain then noise: many survive only if sorted properly
    a = [1, 1]
    while len(a) < 30:
        a.append(sum(a))
    a += [rng.randint(1, 10**9) for _ in range(n - len(a))]
    rng.shuffle(a)
    tests.append(fmt(a))
    return tests

